import type { Card } from "~/lib/sequence";
import logoStarArt from "./assets/logo-star.svg?url&no-inline";

// Card faces and board tiles are generated by `generate-cards.js`
// (`bun run cards:generate`). Each file is a standalone SVG document with its
// own <defs> ids (#suit, #sc, …); importing them as URLs keeps those id spaces
// separate — inlining several faces into one page would make every card
// reference the first card's clip paths.
const cardArt = import.meta.glob<string>("./assets/cards/*.svg", {
  eager: true,
  query: "?url&no-inline",
  import: "default",
});
const tileArt = import.meta.glob<string>("./assets/tiles/*.svg", {
  eager: true,
  query: "?url&no-inline",
  import: "default",
});

function asset(map: Record<string, string>, path: string): string {
  const url = map[`./assets/${path}`];
  if (!url) {
    throw new Error(
      `Missing generated artwork ${path}. Run \`bun run cards:generate\`.`,
    );
  }
  return url;
}

/** Generated file stem for a card: rank + engine suit code (e.g. "7-h"). */
function artKey(card: Card): string {
  const suit = card.suit.toLowerCase();
  if (card.rank === "J") {
    // Spades/hearts are one-eyed (remove a chip); diamonds/clubs are two-eyed
    // (wild placement). The engine owns this rule; mirror it for the art only.
    const eyed = card.suit === "S" || card.suit === "H" ? "one" : "two";
    return `jack-${eyed}-eyed-${suit}`;
  }
  return `${card.rank.toLowerCase()}-${suit}`;
}

export default function PlayingCard(props: {
  card: Card;
  /** square-small: board tile (1:1). full: complete face (304:424). */
  variant: "square-small" | "full";
}) {
  const src = () =>
    props.variant === "full"
      ? asset(cardArt, `cards/${artKey(props.card)}.svg`)
      : asset(tileArt, `tiles/${artKey(props.card)}.svg`);

  return (
    <img
      class={[
        "game-card block h-full w-full select-none object-contain",
        {
          "aspect-square": props.variant === "square-small",
          "aspect-[304/424]": props.variant === "full",
        },
      ]}
      src={src()}
      alt=""
      aria-hidden="true"
      draggable={false}
    />
  );
}

/**
 * The corner FREE spaces use the Hilera star mark on the brand pink rather
 * than a generated card tile.
 */
export function FreeSpace() {
  return (
    <div class="seq-free-tile">
      <img
        class="seq-free-star"
        src={logoStarArt}
        alt=""
        aria-hidden="true"
        draggable={false}
      />
    </div>
  );
}